export const getBffGraphNeighborsUrl = (documentId: string,
    params?: BffGraphNeighborsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/bff/graph/${documentId}/neighbors?${stringifiedParams}` : `/bff/graph/${documentId}/neighbors`
}

